# Notes written when the list was not read; replaced now that it has been.
RENOTE = {
 'sarah-lawrence-college': L('Sarah Lawrence organises study by disciplines rather than conventional majors; the names below are disciplines from its list.',
   'Sarah Lawrence строит обучение по дисциплинам, а не по обычным основным специальностям; ниже — дисциплины из её списка.'),
 'chapman-university': L('From Chapman’s list of degree programmes, which names each bachelor’s degree.', 'Из списка программ Chapman, где названа каждая степень бакалавра.'),
 'goucher-college': None,
 'university-of-oklahoma': L('From the “Find your Major” list on the university’s admissions site.', 'Из списка «Find your Major» на сайте приёма университета.'),
}
import io, json, os, re
_ru = io.open(os.path.join(us3_edit.ROOT, 'data/i18n/ru.js'), encoding='utf-8').read()
def ru_of(en):
    """The Russian text ru.js already has for an English string."""
    m = re.search(r'(?m)^\s*%s:\s*("(?:[^"\\]|\\.)*")' % re.escape(json.dumps(en, ensure_ascii=False)), _ru)
    assert m, en
    return json.loads(m.group(1))

head, recs = us3_edit.load()
D = us3_edit.by_id(recs)
assert len(EV) == 38
for uid, more in EXTRA.items():
    assert not set(more) & set(EV[uid]), uid
    EV[uid].update(more)
for uid, ev in EV.items():
    r = D[uid]
    url = r['links']['programs']
    drops = DROPS.get(uid, {})
    old = [t for t in r['programs'] if t != 'other']
    assert set(old) | set(EXTRA.get(uid, {})) == set(ev) | set(drops), (uid, set(old) ^ (set(ev) | set(drops)))
    tags = [t for t in ORDER if t in ev]
    r['programs'] = tags
    r['englishTaughtPrograms'] = list(tags)      # the language of instruction of these institutions is English
    r['programsBasis'] = 'evidence'
    r.pop('programsStatus', None)
    r['programEvidence'] = {}
    for t in tags:
        name, u = ev[t] if isinstance(ev[t], tuple) else (ev[t], url)
        r['programEvidence'][t] = {'program': name, 'level': 'bachelor', 'language': 'English', 'url': u, 'checked': WHEN.get(uid, V)}
    if drops:
        r['fieldNotes'] = dict((t, {'kind': k, 'note': n, 'url': url, 'checked': V}) for t, (k, n) in drops.items())
    if uid in RENOTE:
        r['programNote'] = RENOTE[uid]
    if uid in NOTE:
        prev = r.get('programNote')
        r['programNote'] = L(prev + ' ' + NOTE[uid], ru_of(prev) + ' ' + NOTE[uid].ru) if prev else NOTE[uid]
    ver = r['verification']
    ver['unconfirmed'] = [x for x in ver['unconfirmed'] if x not in ('list of majors', 'full list of majors')]
    if 'list of majors' not in ver['checked']: ver['checked'].append(L('list of majors', 'список программ'))
    lab = L('%s — official list of undergraduate programmes' % r['shortName'], '%s — официальный список программ бакалавриата' % r['shortName'])
    if not any(s['url'] == url for s in r['sources']): r['sources'].append({'label': lab, 'url': url})

# Babson: one degree, the areas are its concentrations.
b = D['babson-college']
b['programsBasis'] = 'concentrations'
b.pop('programsStatus', None)
b['links']['programs'] = 'https://www.babson.edu/undergraduate/academics/concentrations/'
if not any(s['url'] == b['links']['programs'] for s in b['sources']):
    b['sources'].append({'label': L('Babson College — undergraduate concentrations', 'Babson College — концентрации бакалавриата'), 'url': b['links']['programs']})

us3_edit.save(head, recs)
left = [r['id'] for r in recs if r['programs'] and r.get('programsBasis') not in ('evidence', 'concentrations', 'transfer')]
print('evidence for %d more records; still from keyword matching (%d): %s' % (len(EV), len(left), left))
flush()
